sp_widget.client_script:
api.controller = function() {

    var c = this;

    /* =========================
       SEARCH
       ========================= */

    c.searchText = '';

    c.search = function() {
        c.server.update();
    };


    /* =========================
       NEW COMPLAINT
       ========================= */

    c.newComplaint = function() {

        window.location.href =
            '?id=environmental_report_pollution' +
            '&table=x_snc_environmen_0_complaint' +
            '&sys_id=-1';

    };

};

sp_widget.css:
.ec-complaints-card {
  background: #ffffff;
  border: 1px solid #e3ece9;
  border-radius: 14px;
  padding: 24px;
  margin-top: 18px;
  box-shadow: 0 4px 16px rgba(0, 70, 60, 0.08);
}

.ec-list-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.ec-list-header h2 {
  margin: 0;
  color: #075e54;
  font-size: 23px;
  font-weight: 700;
}

.ec-list-header p {
  margin: 5px 0 0;
  color: #70817e;
  font-size: 13px;
}

.ec-new-btn {
  border: none;
  background: #0b8275;
  color: #ffffff;
  padding: 11px 18px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: .2s;
}

.ec-new-btn:hover {
  background: #075e54;
}

.ec-new-btn span {
  font-size: 18px;
  margin-right: 5px;
}

.ec-search-row {
  display: flex;
  gap: 10px;
  margin-bottom: 18px;
}

.ec-search-box {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid #d6e3df;
  border-radius: 8px;
  padding: 0 12px;
  background: #ffffff;
}

.ec-search-box input {
  width: 100%;
  border: none;
  outline: none;
  padding: 11px 5px;
  font-size: 13px;
}

.ec-search-btn {
  border: 1px solid #c8e3dd;
  background: #eaf6f3;
  color: #075e54;
  padding: 0 18px;
  border-radius: 8px;
  font-weight: 600;
  cursor: pointer;
}

.ec-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.ec-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.ec-table th {
  background: #eff7f5;
  color: #075e54;
  text-align: left;
  padding: 13px 12px;
  border-bottom: 1px solid #d9e7e3;
  font-weight: 700;
  white-space: nowrap;
}

.ec-table td {
  padding: 13px 12px;
  border-bottom: 1px solid #edf2f1;
  color: #435653;
}

.ec-table-row:hover {
  background: #f8fcfb;
}

.ec-id {
  color: #087c70;
}

.ec-status,
.ec-priority {
  display: inline-block;
  padding: 5px 9px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.status-progress,
.status-investigation,
.status-assigned {
  background: #fff4d8;
  color: #9a6800;
}

.status-completed,
.status-closed,
.status-resolved {
  background: #e5f7ed;
  color: #17834b;
}

.status-open,
.status-new {
  background: #e8f1ff;
  color: #2567ad;
}

.priority-high,
.priority-critical {
  background: #ffe4e1;
  color: #c43d32;
}

.priority-medium {
  background: #fff1d8;
  color: #a56b00;
}

.priority-low {
  background: #e5f7ed;
  color: #16834a;
}

.ec-empty {
  text-align: center;
  padding: 35px !important;
  color: #7c8c89 !important;
}

.ec-footer {
  margin-top: 14px;
  color: #7a8986;
  font-size: 12px;
}

sp_widget.script:
(function() {

    data.complaints = [];

    var gr = new GlideRecord('x_snc_environmen_0_complaint');

    gr.orderByDesc('sys_created_on');
    gr.setLimit(50);
    gr.query();

    while (gr.next()) {

        var complaint = {};

        // Complaint number
        complaint.id = gr.getDisplayValue('number');

        // Complaint type
        if (gr.isValidField('complaint_type')) {
            complaint.type = gr.getDisplayValue('complaint_type');
        } else {
            complaint.type = '';
        }

        // Location
        if (gr.isValidField('location')) {
            complaint.location = gr.getDisplayValue('location');
        } else {
            complaint.location = '';
        }

        // Priority
        if (gr.isValidField('priority')) {
            complaint.priority = gr.getDisplayValue('priority');
        } else {
            complaint.priority = '';
        }

        // Status
        if (gr.isValidField('status')) {
            complaint.status = gr.getDisplayValue('status');
        } else {
            complaint.status = '';
        }

        // Created date
        complaint.created = gr.getDisplayValue('sys_created_on');


        // CSS class for priority
        var priorityText = (complaint.priority || '').toLowerCase();

        if (priorityText.indexOf('high') >= 0 ||
            priorityText.indexOf('critical') >= 0) {

            complaint.priorityClass = 'high';

        } else if (priorityText.indexOf('medium') >= 0) {

            complaint.priorityClass = 'medium';

        } else {

            complaint.priorityClass = 'low';
        }


        // CSS class for status
        var statusText = (complaint.status || '').toLowerCase();

        if (statusText.indexOf('progress') >= 0) {

            complaint.statusClass = 'progress';

        } else if (statusText.indexOf('investigation') >= 0) {

            complaint.statusClass = 'investigation';

        } else if (statusText.indexOf('assigned') >= 0) {

            complaint.statusClass = 'assigned';

        } else if (statusText.indexOf('completed') >= 0) {

            complaint.statusClass = 'completed';

        } else if (statusText.indexOf('closed') >= 0) {

            complaint.statusClass = 'closed';

        } else if (statusText.indexOf('resolved') >= 0) {

            complaint.statusClass = 'resolved';

        } else {

            complaint.statusClass = 'new';
        }


        data.complaints.push(complaint);
    }

})();
